using System;
using System.Globalization;
using System.Linq;
using System.Text.RegularExpressions;

namespace PulsoIT {
    public sealed class FindingExplanation {
        public string Title,Meaning,Impact,Next,Check,Category="other";
        public bool Known;
    }
    public static class PlainLanguage {
        // Los mensajes de Windows son datos. Nunca se ejecutan ni se usan como instrucciones.
        public static string Text(string value,int length=400){value=Regex.Replace(value??"",@"[\x00-\x1F\x7F]+"," ").Trim();return value.Length>length?value.Substring(0,length)+"…":value;}
        public static bool Problem(Finding f){return f.State=="critical"||f.State=="warning";}
        public static bool Provider(Finding f,params string[] names){return names.Any(n=>string.Equals(n,f.MetaText("Provider"),StringComparison.OrdinalIgnoreCase));}
        public static int EventId(Finding f){int n;return int.TryParse(f.MetaText("Id"),out n)?n:-1;}
        public static string EventKind(Finding f){
            if(f.Code!="event.group")return "";int id=EventId(f);
            if(Provider(f,"Microsoft-Windows-Kernel-Power")&&id==41)return "restart";
            if(Provider(f,"EventLog")&&id==6008)return "restart";
            if(Provider(f,"Microsoft-Windows-WER-SystemErrorReporting","WER-SystemErrorReporting","BugCheck")&&id==1001)return "stop";
            if(Provider(f,"Microsoft-Windows-WHEA-Logger"))return "hardware";
            if(Provider(f,"disk","Microsoft-Windows-Disk")&&id==7)return "storage-integrity";
            if(Provider(f,"Ntfs","Microsoft-Windows-Ntfs")&&id==55)return "storage-integrity";
            if((Provider(f,"disk","Microsoft-Windows-Disk")&&new[]{51,153}.Contains(id))||(Provider(f,"storahci","stornvme","storport","Microsoft-Windows-StorPort")&&id==129))return "storage-delay";
            if((Provider(f,"Application Error")&&id==1000)||(Provider(f,"Application Hang")&&id==1002))return "application";
            if(Provider(f,"Service Control Manager")&&new[]{7000,7001,7009,7011,7023,7024,7031,7034}.Contains(id))return "service";
            if(Provider(f,"Microsoft-Windows-DNS-Client")&&id==1014)return "dns-event";
            if(Provider(f,"Microsoft-Windows-DeviceManagement-Enterprise-Diagnostics-Provider"))return "mdm-event";
            if(Provider(f,"Microsoft-Windows-PrintService"))return "print-event";
            return "";
        }
        static FindingExplanation Make(string title,string meaning,string impact,string next,string check,string category){return new FindingExplanation{Title=title,Meaning=meaning,Impact=impact,Next=next,Check=check,Category=category,Known=true};}
        public static FindingExplanation Explain(Finding f){
            string title=Text(f.Title),subject=Text(f.MetaText("Subject"),100),kind=EventKind(f);bool bad=Problem(f);
            if(f.State=="unknown")return Make(title,"Pulso IT no ha podido completar esta comprobación: "+Text(f.Summary),"No demuestra una avería, pero deja una parte del diagnóstico pendiente.",Text(f.Next),"Repite con el componente disponible o con el permiso delegado necesario. No hace falta conceder administración completa por defecto.","pending");
            if(f.Code=="event.group"){
                string time=Text(f.MetaText("LastSeenUtc"));DateTime date;if(DateTime.TryParse(time,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out date))time=date.ToLocalTime().ToString("g");
                string seen=" Registro más reciente: "+time+". "+Text(f.MetaText("Occurrences"))+" apariciones en la muestra.";
                string who=subject.Length==0?"":" Elemento comunicado: "+subject+".";
                switch(kind){
                    case "restart":return Make("Windows no se cerró con normalidad","Windows ha registrado un reinicio o apagado no limpio."+seen,"Confirma el cierre anómalo, pero no distingue un bloqueo, un error de parada, un corte eléctrico o un apagado forzado.","Contrasta la hora con errores de parada y WHEA; no sustituyas la fuente de alimentación basándote solo en este registro.","Si hay un error de parada en el mismo episodio, revisa primero ese error y los metadatos del volcado.","restart");
                    case "stop":return Make("Windows registró un error de parada","Consta un error de parada del sistema, compatible con una pantalla azul."+seen,"Puede explicar un reinicio. El evento no identifica por sí solo el controlador o componente responsable.","Revisa el código de parada y el volcado con una herramienta de depuración autorizada.","Confirma que la fecha coincide con el reinicio observado por el usuario.","restart");
                    case "hardware":return Make("Windows recibió un aviso de hardware","WHEA ha registrado una condición de hardware o firmware."+seen,"Algunos errores WHEA son corregidos y otros no. Este registro no permite decidir qué pieza cambiar.","Contrasta nivel, detalle, recurrencia y coincidencia con bloqueos o errores de parada.","Distingue corregido/no corregido en el evento y valida el dispositivo con el responsable.","hardware");
                    case "storage-integrity":return Make("El almacenamiento requiere atención","Windows ha comunicado un error de bloque o de estructura del sistema de archivos."+seen,"Existe una señal de integridad que merece prioridad; no identifica por sí sola el componente físico culpable.","Identifica disco/volumen y comprueba las copias de los datos antes de decidir cualquier intervención.","Contrasta el evento con la salud del dispositivo y otros errores del mismo volumen. Pulso IT no ejecuta reparaciones.","storage");
                    case "storage-delay":return Make("Una operación de disco se retrasó o tuvo que repetirse","El subsistema de almacenamiento registró una espera, reintento o reinicio de una operación."+seen,"Puede producir pausas. También puede deberse a carga, controladores, controladora o almacenamiento remoto; no prueba que el disco esté roto.","Reproduce el fallo y observa latencia/actividad; identifica el dispositivo del evento.","Comprueba si los retrasos se repiten durante la lentitud y en el mismo almacenamiento.","storage");
                    case "application":return Make("Una aplicación falló o dejó de responder","Windows ha registrado un cierre con error o un bloqueo de aplicación."+who+seen,"Afecta a esa aplicación; no implica necesariamente un fallo de todo el PC.","Contrasta aplicación, versión, módulo y hora del fallo con lo que estaba haciendo el usuario.","Reproduce la misma operación. El módulo mencionado no demuestra por sí solo que sea la causa.","application");
                    case "service":return Make("Un servicio no inició, no respondió o terminó con error","El administrador de servicios ha registrado un fallo de servicio."+who+seen,"Puede afectar a las funciones que dependen de él. Un evento pasado no demuestra que siga detenido.","Contrasta el servicio exacto con su estado actual, dependencias y código de salida.","No reinicies servicios automáticamente: confirma antes si el servicio sigue fallando y qué función está afectada.","service");
                    case "dns-event":return Make("Hubo una espera al resolver un nombre","Windows registró una consulta de nombre sin respuesta a tiempo."+seen,"Puede explicar un acceso lento por nombre. No demuestra que toda la red o el servidor estén caídos.","Prueba el mismo nombre en Red y comprueba DNS corporativos, VPN y sufijos.","Contrasta la prueba actual con la hora del evento; puede haber sido transitorio.","network");
                    case "mdm-event":return Make("La gestión del dispositivo dejó un registro para revisar","El proveedor MDM ha comunicado un evento en la ventana consultada."+seen,"El efecto depende de la operación y del código concretos; no basta para declarar el equipo fuera de cumplimiento.","Relaciona el código y la operación con la tarea afectada y el portal de gestión.","La aplicación solo verifica evidencias locales; el portal debe confirmar el estado de gestión.","management");
                    case "print-event":return Make("Windows registró una incidencia de impresión","El proveedor de impresión ha comunicado un evento."+seen,"Puede estar relacionado con una impresora o un trabajo; falta confirmar que siga fallando.","Contrasta la impresora del mensaje con su estado, cola y Spooler.","Comprueba si el mismo trabajo vuelve a fallar; no se borra la cola.","printing");
                }
                return new FindingExplanation{Title="Registro de Windows pendiente de interpretar",Meaning="El proveedor "+Text(f.MetaText("Provider"),120)+" dejó el evento "+Text(f.MetaText("Id"),20)+"."+seen,Impact="No hay una regla específica fiable para deducir su efecto. Su nivel de error no demuestra que explique el síntoma.",Next="Relaciona el mensaje, la operación y la hora con el fallo. Consulta la documentación del proveedor si se repite.",Check="No se atribuye una causa a partir de un identificador sin conocer el proveedor.",Category="event"};
            }
            switch(f.Code){
                case "memory.snapshot":return Make(bad?"Queda poca memoria física disponible":"La memoria física no supera el umbral de aviso",bad?"En esta lectura la RAM está muy ocupada.":"Esta lectura no indica RAM física casi agotada.","Una instantánea no demuestra presión sostenida, fuga de memoria ni necesidad de ampliar RAM.","Observa 30/60 segundos mientras ocurre la lentitud para contrastar compromiso, paginación y disco.","La conclusión gana fuerza si el compromiso elevado y la paginación coinciden durante el mismo intervalo.","memory");
                case "cpu.snapshot":return Make(bad?"La CPU estuvo muy ocupada en la consulta breve":"No hubo CPU alta en las tres lecturas breves",Text(f.Summary),"El intervalo es corto y puede perder un fallo intermitente.","Reproduce la tarea lenta durante la observación de 30/60 segundos.","Comprueba si el mismo proceso mantiene la carga durante el síntoma.","cpu");
                case "disk.space":return Make(bad?"Queda poco espacio en "+Text(f.MetaText("Identity"),40):"El volumen dispone de espacio por encima del umbral de aviso",Text(f.Summary),"El poco espacio puede impedir actualizaciones o escritura; no demuestra que el disco tenga daño físico.",bad?"Comprueba si es el volumen de Windows o de la aplicación y revisa qué ocupa espacio antes de eliminar datos.":"No es necesario liberar espacio por esta comprobación aislada.","Comprueba también los GB libres y las necesidades de la aplicación, no solo el porcentaje.","space");
                case "disk.reliability":return Make(bad?"El dispositivo comunica un indicador de fiabilidad que requiere revisión":"Los contadores disponibles no superan los umbrales de aviso",Text(f.Summary),"Los errores pueden ser acumulados; desgaste, temperatura y cobertura dependen del dispositivo.",bad?"Revisa los valores concretos y su evolución; comprueba las copias antes de intervenir.":"Conserva el contexto: ausencia de aviso en estos contadores no equivale a una prueba física completa.","No atribuyas la lentitud a daño físico sin otras evidencias.","storage");
                case "disk.health":case "disk.volume":case "disk.dirty":return Make(bad?"Windows comunica una condición de almacenamiento que requiere revisión":"No hay aviso en el estado de almacenamiento consultado",Text(f.Summary),"El estado comunicado por el proveedor no sustituye una prueba física ni explica por sí solo el síntoma.",Text(f.Next),"Relaciona el disco/volumen exacto con los eventos y las mediciones.","storage");
                case "network.apipa":return Make("Una interfaz activa tiene dirección de autoconfiguración","La interfaz tiene una IPv4 169.254.x.x en lugar de una dirección de la red esperada.","Puede impedir acceder a recursos, si esa es la interfaz que se está usando. No prueba por sí sola que el servidor DHCP esté averiado.","Confirma el adaptador usado y si se esperaba DHCP o una IP estática.","Revisa la dirección, red/VLAN y conectividad del adaptador afectado.","network");
                case "network.dns":return Make(bad?"No se pudo resolver el nombre indicado":"El nombre indicado responde a la consulta DNS",Text(f.Summary),bad?"Puede impedir el acceso por nombre; una entrada hosts o la caché de otra aplicación podrían dar otro resultado.":"Un nombre resuelto no garantiza que su servicio acepte conexiones.",bad?"Comprueba el nombre, DNS, VPN y sufijos y contrasta la prueba TCP al mismo destino.":"Comprueba que la dirección resuelta es la esperada y contrasta el puerto de la aplicación.","Distingue resolución de nombre, conexión TCP y autenticación.","network");
                case "network.tcp":return Make(bad?"La conexión al puerto no se completó":"Se pudo abrir el puerto indicado",Text(f.Summary),bad?"La prueba no distingue un puerto erróneo, servicio sin escucha, ruta, firewall o destino que no responde.":"Solo confirma una conexión TCP; no valida acceso del usuario ni funcionamiento de la aplicación.",Text(f.Next),"Contrasta el mismo equipo y puerto; no mezcles pruebas de destinos distintos.","network");
                case "network.https":return Make(bad?"La comprobación HTTPS necesita revisión":"El servicio devolvió una respuesta HTTPS",Text(f.Summary),"Una respuesta 401/403/404/405 no demuestra una caída; un error TLS puede depender del nombre, reloj, confianza o proxy.",Text(f.Next),"No se han enviado credenciales ni se ha omitido la validación del certificado.","network");
                case "network.address":case "network.dns.missing":return Make(title,Text(f.Summary),"Puede limitar el acceso de las aplicaciones; depende del adaptador y de la red prevista.",Text(f.Next),"Comprueba la interfaz realmente utilizada por el recurso afectado.","network");
                case "security.active":return Make(bad?"Defender comunica amenazas activas":"Defender no comunica amenazas activas en esta consulta",Text(f.Summary),bad?"Es una señal de seguridad que requiere atención, aunque no explica necesariamente todos los síntomas.":"No es un análisis antivirus nuevo ni demuestra ausencia de malware.",bad?"Sigue el procedimiento de seguridad corporativo y remite la evidencia al responsable.":"Revisa también el producto de protección asignado y sus firmas.","El diagnóstico solo lee el estado existente; no elimina ni pone archivos en cuarentena.","security");
                case "security.status":return Make(bad?"Defender no comunica toda su protección habitual":"Se ha leído el estado de Defender",Text(f.Summary),"El modo pasivo puede ser previsto si otro producto protege el equipo. El registro de un antivirus no prueba que esté activo.","Confirma qué producto debe proteger este equipo y contrasta su estado en la consola corporativa.","No se desactiva ni se reactiva ningún producto desde Pulso IT.","security");
                case "security.signatures":return Make(bad?"Las firmas de Defender necesitan revisión":"Se ha obtenido la fecha de las firmas",Text(f.Summary),"La fecha debe interpretarse con el reloj, el modo de Defender y la política del producto asignado.",Text(f.Next),"Una firma reciente no equivale a un análisis limpio del equipo.","security");
                case "service.errors":return Make(bad?"Hay servicios automáticos detenidos con código de error":"No se encontraron servicios automáticos detenidos con código de error relevante",Text(f.Summary),"Un servicio detenido por desencadenador o que nunca se intentó iniciar puede ser normal. Solo se destacan los códigos distintos de 0 y 1077.",Text(f.Next),"Relaciona el servicio exacto con su evento y con la función afectada.","service");
                case "printer.queue":case "printer.state":case "printer.spooler":return Make(f.Code=="printer.spooler"&&bad?"El servicio de impresión está detenido":bad?"La impresión requiere revisión":"No hay aviso en esta comprobación de impresión",Text(f.Summary),"Los trabajos antiguos pueden estar pausados a propósito y el estado de una impresora depende del controlador.",Text(f.Next),"Confirma la impresora afectada y su puerto. No se imprimen pruebas ni se borran trabajos.","printing");
                case "rdp.config":case "rdp.listen":case "rdp.service":return Make(bad?"RDP está habilitado pero una comprobación local no es correcta":"Se ha leído la configuración de Escritorio remoto local",Text(f.Summary),"Estas comprobaciones se refieren a conexiones entrantes a este PC. Tener RDP deshabilitado puede ser la política prevista.",Text(f.Next),"No explica por sí solo el acceso de este PC a otro servidor RDP.","rdp");
                case "device.errors":return Make(bad?"Windows comunica dispositivos con incidencias":"No hay incidencias de dispositivos fuera de los deshabilitados",Text(f.Summary),"Un dispositivo deshabilitado intencionadamente no es una avería. Los otros códigos deben asociarse al dispositivo afectado.",Text(f.Next),"Comprueba si el dispositivo presta la función que falla antes de cambiar un controlador.","device");
                case "mdm.task":return Make(bad?"Una tarea de gestión terminó con un código para revisar":"No hay error de ejecución en el estado de tarea consultado",Text(f.Summary),"Una última ejecución antigua no demuestra un fallo actual ni incumplimiento en Intune.",Text(f.Next),"Contrasta fecha, tarea y estado del portal; Pulso IT no fuerza sincronizaciones.","management");
                case "vpn.events":return Make(bad?"El cliente VPN integrado registró incidencias":"No hay eventos de error visibles del cliente VPN integrado",Text(f.Summary),"Un intento fallido anterior no demuestra que la VPN siga fallando; no se verifica la autenticación ni los clientes de terceros.","Contrasta hora, perfil, servidor y código del mismo intento con la configuración de red y DNS.","No se deducen credenciales incorrectas, fallo del servidor o bloqueo de puertos sin evidencia del error concreto.","vpn");
                case "event.coverage":return Make("Alcance de los registros leídos",Text(f.Summary),"Si se alcanza el límite puede haber registros relevantes fuera de la muestra.",Text(f.Next),"La ausencia de un evento solo se refiere a esta ventana y a los canales consultados.","coverage");
                case "observation.summary":return Make("Medición del rendimiento durante un intervalo",Text(f.Summary),"Las gráficas muestran si la carga coincide con el síntoma; un intervalo corto no captura todos los fallos intermitentes.","Lee Diagnóstico para ver qué señales se han correlacionado.","Las series sin datos quedan sin verificar.","performance");
            }
            string meaning=f.State=="good"?"Esta comprobación no ha encontrado su condición de aviso.":bad?"La comprobación ha encontrado una condición que necesita contexto.":"Este resultado aporta información de contexto; por sí solo no indica una avería.";
            return new FindingExplanation{Title=title,Meaning=meaning+" "+Text(f.Summary),Impact="Su alcance se limita a "+Catalog.Get(f.Section).Name+". No demuestra por sí solo la causa del problema.",Next=Text(f.Next),Check="Contrasta el resultado con el síntoma y su momento. Los datos originales están en Datos técnicos.",Category="other"};
        }
        public static string Detail(Finding f){var x=Explain(f);return x.Title+Environment.NewLine+Finding.Label(f.State)+" · "+f.Time.ToString("T")+" · "+Text(f.Context)+Environment.NewLine+Environment.NewLine+"QUÉ SIGNIFICA"+Environment.NewLine+x.Meaning+Environment.NewLine+Environment.NewLine+"CÓMO TE PUEDE AFECTAR"+Environment.NewLine+x.Impact+Environment.NewLine+Environment.NewLine+"QUÉ REVISAR"+Environment.NewLine+x.Next+Environment.NewLine+Environment.NewLine+"CÓMO CONFIRMARLO"+Environment.NewLine+x.Check;}
    }
}
